# =====================================================================
#  manufacturing.map - phishing phrases for industry and production
#  Part of: phishing-detector by Develust Technology
#
#  Format : one regex per line, /pattern/flags (i = case-insensitive,
#           u = UTF-8). No trailing spaces.
#  Note   : PHISH_TEXT scores 0 alone; it only adds points together
#           with a phishing link (PHISH_URL / PHISHING).
#
#  Themes : fake purchase orders / RFQs behind a link, "ready to place
#           orders" + video meeting lures (Zoom / Teams), password-
#           protected catalogs and drawings, fake proforma invoices,
#           supplier bank-detail changes (BEC), fake certificates
#
#  Avoided: "please quote", "request for quotation", "purchase order
#           attached", "proforma invoice attached", "send samples",
#           because factories receive real ones every day.
# =====================================================================

# ===== English =====
# Fake PO / RFQ behind a link
/(view|download|open|access)\s+(the\s+)?(purchase\s+order|p\.?o\.?|rfq|request\s+for\s+quotation|order\s+specifications?|tender\s+documents?)\s+(here|below|online|via\s+(the\s+)?link|on\s+our\s+portal)/i
/(purchase\s+order|rfq|order\s+details)\s+(is\s+|are\s+)?(available|uploaded|shared)\s+(on|via|through)\s+(our\s+)?(portal|link|secure\s+server|cloud)/i
/(new\s+)?(purchase\s+)?order\s+#?\S+\s+(requires|awaiting)\s+(your\s+)?(confirmation|signature|approval)\s+(online|via|here)/i
# "Ready to order" + meeting lures
/we\s+are\s+ready\s+to\s+place\s+(an\s+|our\s+)?(orders?|bulk\s+orders?)\s+with\s+your\s+company/i
/(our\s+)?(manager|director|ceo|purchasing\s+manager)\s+(is\s+asking|would\s+like|requests?)\s+(for\s+)?(a\s+)?(video\s+)?(teams|zoom|skype|google\s+meet|video)\s+(meeting|call|conference)/i
/(can\s+we\s+have|let['’]s\s+schedule)\s+a\s+(zoom|teams|video)\s+(meeting|call)\s+(today|tomorrow)[^.]{0,40}(order|introduction|presentation)/i
/(introduction\s+and\s+)?order\s+presentation/i
# Catalogs / drawings
/(product\s+)?catalog(ue)?\s+(is\s+)?(password[\s-]protected|available\s+(only\s+)?online|via\s+(the\s+)?link)/i
/(technical\s+)?drawings?\s+(and|&)\s+specifications?\s+(are\s+)?(available|uploaded)\s+(via|on|through)/i
/(enable\s+(editing|content|macros)|password\s+is)\s+(to\s+view|for\s+the)\s+(order|catalog|drawings?|specification)/i
# Proforma / invoices
/(download|view)\s+(the\s+)?(proforma|pro-forma|commercial)\s+invoice\s+(here|online|via\s+(the\s+)?link)/i
# Supplier bank change (BEC)
/(we\s+have\s+)?(changed|updated)\s+(our\s+)?(bank(ing)?|beneficiary)\s+(details|account|information)/i
/(all\s+)?(future\s+)?payments\s+(should|must)\s+(now\s+)?be\s+(made|sent)\s+to\s+(our\s+)?new\s+(bank\s+)?account/i
# Certificates
/(iso|ce|quality)\s+certificate\s+(has\s+)?(expired|will\s+expire|requires\s+renewal)\s+(click|update|renew)/i

# ===== Spanish =====
/(vea|descargue|acceda\s+a)\s+(la\s+)?(orden\s+de\s+compra|solicitud\s+de\s+cotizaci[óo]n|especificaciones)\s+(aqu[íi]|en\s+l[íi]nea|en\s+el\s+enlace)/iu
